function logDevices(label, devices) {
  return; 
  if (!devices || devices.length === 0) {
    console.log(`-- audio device ${label}: (none)`);
    return;
  }

  console.log(`-- ${label}:`);
  devices.forEach(d => {
    if (d) {
      console.log(`  audio device: ${d.id}, name: ${d.name}, type: ${d.type}`);
    }
  });
}

