const chunkArray = (array, size) => {
  const chunks = [];
  for (let i = 0; i < array.length; i += size) {
	chunks.push(array.slice(i, i + size));
  }
  return chunks;
};
	
const getSafeTimestamp = (message) =>
  new Date(message.timestamp)
    .toISOString()
    .replace(/[:]/g, '-')
    .replace('T', '_')
    .split('.')[0];

